script:
(function() {
	if (typeof L === 'undefined') {
		const link = document.createElement('link');
		link.rel = 'stylesheet';
		link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
		link.integrity = 'sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=';
		link.crossOrigin = '';
		document.head.appendChild(link);

		const script = document.createElement('script');
		script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
		script.integrity = 'sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=';
		script.crossOrigin = '';
		script.onload = initMap;
		document.head.appendChild(script);
	} else {
		initMap();
	}

	function initMap() {
		const mapEl = root_element.querySelector('#farms-map');
		if (!mapEl) return;

		let map = L.map(mapEl).setView([0, 0], 2);
		let allFarms = [];
		let markers = [];

		// Satellite imagery using Esri World Imagery
		L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
			attribution: 'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community'
		}).addTo(map);

		// Get filter elements
		const countryFilter = root_element.querySelector('#filter-country');
		const districtFilter = root_element.querySelector('#filter-district');
		const cropFilter = root_element.querySelector('#filter-crop');
		const groupFilter = root_element.querySelector('#filter-group');
		const resetBtn = root_element.querySelector('#reset-filters');
		const farmsCount = root_element.querySelector('#farms-count');

		// Load all filter options from respective doctypes
		loadFilterOptions();

		// Fetch farms data
		frappe.call({
			method: 'farmtrace.farm_trace.api.get_farm_locations',
			callback: function(r) {
				if (r.message && r.message.length > 0) {
					allFarms = r.message;
					displayFarms(allFarms);
				} else {
					mapEl.innerHTML = '<div class="text-muted text-center p-5">No farms with location data found.</div>';
				}
			}
		});

		// Load filter options from doctypes
		function loadFilterOptions() {
			// Load Countries
			frappe.call({
				method: 'frappe.client.get_list',
				args: {
					doctype: 'Country',
					fields: ['name'],
					limit_page_length: 0,
					order_by: 'name asc'
				},
				callback: function(r) {
					if (r.message) {
						r.message.forEach(function(country) {
							const option = document.createElement('option');
							option.value = country.name;
							option.textContent = country.name;
							countryFilter.appendChild(option);
						});
					}
				}
			});

			// Load Districts
			frappe.call({
				method: 'frappe.client.get_list',
				args: {
					doctype: 'District',
					fields: ['name'],
					limit_page_length: 0,
					order_by: 'name asc'
				},
				callback: function(r) {
					if (r.message) {
						r.message.forEach(function(district) {
							const option = document.createElement('option');
							option.value = district.name;
							option.textContent = district.name;
							districtFilter.appendChild(option);
						});
					}
				}
			});

			// Load Crop Types
			frappe.call({
				method: 'frappe.client.get_list',
				args: {
					doctype: 'Crop',
					fields: ['name'],
					limit_page_length: 0,
					order_by: 'name asc'
				},
				callback: function(r) {
					if (r.message) {
						r.message.forEach(function(crop) {
							const option = document.createElement('option');
							option.value = crop.name;
							option.textContent = crop.name;
							cropFilter.appendChild(option);
						});
					}
				}
			});

			// Load Farmer Groups
			frappe.call({
				method: 'frappe.client.get_list',
				args: {
					doctype: 'Farmer Group',
					fields: ['name'],
					limit_page_length: 0,
					order_by: 'name asc'
				},
				callback: function(r) {
					if (r.message) {
						r.message.forEach(function(group) {
							const option = document.createElement('option');
							option.value = group.name;
							option.textContent = group.name;
							groupFilter.appendChild(option);
						});
					}
				}
			});
		}

		// Display farms on map
		function displayFarms(farms) {
			// Clear existing markers
			markers.forEach(marker => map.removeLayer(marker));
			markers = [];

			const bounds = [];

			farms.forEach(function(farm) {
				const lat = parseFloat(farm.latitude);
				const lng = parseFloat(farm.longitude);
				if (!isNaN(lat) && !isNaN(lng)) {
					const marker = L.marker([lat, lng]).addTo(map);
					const popupContent = '<b>' + (farm.farm_name || farm.name) + '</b><br>' +
						(farm.farmer ? 'Farmer: ' + farm.farmer + '<br>' : '') +
						(farm.village ? 'Village: ' + farm.village + '<br>' : '') +
						(farm.country ? 'Country: ' + farm.country + '<br>' : '') +
						(farm.district ? 'District: ' + farm.district + '<br>' : '') +
						(farm.crop_type ? 'Crop: ' + farm.crop_type + '<br>' : '') +
						(farm.farmer_group ? 'Group: ' + farm.farmer_group + '<br>' : '') +
						'<a href="/app/farm/' + encodeURIComponent(farm.name) + '" target="_blank">View Farm</a>';
					marker.bindPopup(popupContent);
					markers.push(marker);
					bounds.push([lat, lng]);
				}
			});

			if (bounds.length > 0) {
				map.fitBounds(bounds, { padding: [50, 50], maxZoom: 15 });
			}

			// Update count
			farmsCount.textContent = `Showing ${farms.length} of ${allFarms.length} farms`;
		}

		// Filter farms based on selected filters
		function applyFilters() {
			const selectedCountry = countryFilter.value;
			const selectedDistrict = districtFilter.value;
			const selectedCrop = cropFilter.value;
			const selectedGroup = groupFilter.value;

			const filteredFarms = allFarms.filter(farm => {
				return (!selectedCountry || farm.country === selectedCountry) &&
					   (!selectedDistrict || farm.district === selectedDistrict) &&
					   (!selectedCrop || farm.crop_type === selectedCrop) &&
					   (!selectedGroup || farm.farmer_group === selectedGroup);
			});

			displayFarms(filteredFarms);
		}

		// Add event listeners to filters
		countryFilter.addEventListener('change', applyFilters);
		districtFilter.addEventListener('change', applyFilters);
		cropFilter.addEventListener('change', applyFilters);
		groupFilter.addEventListener('change', applyFilters);

		// Reset filters
		resetBtn.addEventListener('click', function() {
			countryFilter.value = '';
			districtFilter.value = '';
			cropFilter.value = '';
			groupFilter.value = '';
			displayFarms(allFarms);
		});
	}
})();

