script:
var root = root_element;
// The desk wraps every Custom HTML Block in its own widget box (title, padding
// and background). Each panel below ships its own card, so the extra chrome is
// removed to avoid a duplicated heading and a box inside a box.
var ft_host = root.host;
var ft_widget = ft_host && ft_host.closest ? ft_host.closest(".widget") : null;
if (ft_widget) {
    ft_widget.style.background = "transparent";
    ft_widget.style.padding = "0";
    ft_widget.style.borderRadius = "0";
    var ft_label = ft_widget.querySelector(".widget-label");
    if (ft_label) ft_label.style.display = "none";
    var ft_body = ft_widget.querySelector(".widget-body");
    if (ft_body) ft_body.style.paddingTop = "0";
}
var esc = function (value) {
    if (value === null || value === undefined) return "";
    var mapping = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
    return String(value).replace(/[&<>"']/g, function (character) {
        return mapping[character] || character;
    });
};
var pick = function (key) { return root.querySelector('[data-ft="' + key + '"]'); };
var set_text = function (key, value) {
    var element = pick(key);
    if (element) element.textContent = value;
};
var fill = function (key, html) {
    var element = pick(key);
    if (element) element.innerHTML = html;
};
var num = function (value, decimals) {
    var amount = Number(value || 0);
    var places = decimals === undefined ? 2 : decimals;
    if (window.format_number) return window.format_number(amount, null, places);
    return amount.toFixed(places);
};
var day = function (value) { return value ? frappe.datetime.str_to_user(value) : "—"; };
var empty = function (message) { return '<p class="ft-muted ft-empty">' + esc(message) + '</p>'; };
var show_error = function () { fill("rows", empty("Could not load this panel.")); };
var load = function (method, done) {
    frappe.call({
        method: method,
        args: {},
        callback: function (response) { done(response.message || {}); },
        error: show_error,
    });
};
var pill = function (status) {
    var classes = { Closed: "ft-closed", Submitted: "ft-info", Draft: "ft-draft", Cancelled: "ft-draft" };
    return '<span class="ft-pill ' + (classes[status] || "ft-draft") + '">' + esc(status || "—") + "</span>";
};
var bar_color = function (index) {
    var palette = ["#16a34a", "#2490ef", "#f59e0b", "#8b5cf6", "#ef4444", "#0d9488"];
    return palette[index % palette.length];
};
var table = function (columns, body) {
    var head = "";
    for (var index = 0; index < columns.length; index++) {
        head += '<th class="' + (columns[index][1] || "") + '">' + esc(columns[index][0]) + "</th>";
    }
    return '<table class="ft-table"><thead><tr>' + head + "</tr></thead><tbody>" + body + "</tbody></table>";
};
var row_count = function (rows) { return rows && rows.length ? rows.length : 0; };

        load("farmtrace.farm_trace.api.purchase_dashboard.get_compliance_summary", function (message) {
            var rows = message.rows || [];
            var summary = message.summary || {};
            set_text("meta", num(summary.farms, 0) + " farms \u00b7 " + num(summary.hectares) + " ha");
            if (!rows.length) {
                fill("rows", empty("No farm is enrolled in a certification standard yet."));
                return;
            }
            fill("rows", rows.map(function (row, index) {
                var sub = num(row.verified, 0) + " of " + num(row.farms, 0) + " verified";
                return '<div class="ft-row">'
                    + '<span class="ft-bar" style="background:' + bar_color(index) + '"></span>'
                    + '<span class="ft-row-label">' + esc(row.standard)
                    + '<span class="ft-row-sub">' + esc(sub) + '</span></span>'
                    + '<span class="ft-row-value">' + esc(num(row.farms, 0) + " farms \u00b7 " + num(row.hectares) + " ha")
                    + '</span></div>';
            }).join(""));
        });

style:
.ft-card {
    height: 100%;
    box-sizing: border-box;
    padding: 1rem 1.1rem;
    border: 1px solid var(--border-color, #e2e2e2);
    border-radius: var(--border-radius-md, 8px);
    background: var(--fg-color, #fff);
}
.ft-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: .75rem;
    margin-bottom: .7rem;
}
.ft-title {
    display: flex;
    align-items: center;
    gap: .45rem;
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    line-height: 1.3;
    color: var(--text-color, #1f272e);
}
.ft-title::before {
    content: '';
    width: 3px;
    height: 1.1em;
    border-radius: 2px;
    background: #16a34a;
    flex: 0 0 auto;
}
.ft-sub {
    margin: .2rem 0 0 .45rem;
    font-size: .7rem;
    letter-spacing: .04em;
    text-transform: uppercase;
    color: var(--text-muted, #7c8792);
}
.ft-meta {
    font-size: .72rem;
    color: var(--text-muted, #7c8792);
    white-space: nowrap;
}
.ft-rows {
    display: flex;
    flex-direction: column;
}
.ft-row {
    display: flex;
    align-items: center;
    gap: .55rem;
    padding: .4rem 0;
    border-bottom: 1px solid var(--border-color, #f2f4f7);
}
.ft-row:last-child {
    border-bottom: 0;
}
.ft-bar {
    width: 3px;
    height: 1.5rem;
    border-radius: 2px;
    flex: 0 0 auto;
}
.ft-row-label {
    flex: 1 1 auto;
    min-width: 0;
    font-size: .84rem;
    color: var(--text-color, #1f272e);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ft-row-sub {
    display: block;
    font-size: .7rem;
    color: var(--text-muted, #7c8792);
}
.ft-row-value {
    flex: 0 0 auto;
    font-size: .8rem;
    font-variant-numeric: tabular-nums;
    color: var(--text-muted, #7c8792);
    white-space: nowrap;
}
.ft-metrics {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: .55rem .75rem;
    margin-bottom: .7rem;
}
.ft-metric-label {
    display: block;
    font-size: .64rem;
    letter-spacing: .04em;
    text-transform: uppercase;
    color: var(--text-muted, #7c8792);
}
.ft-metric-value {
    font-size: 1.05rem;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: var(--text-color, #1f272e);
}
.ft-track {
    height: 6px;
    border-radius: 999px;
    background: var(--control-bg, #f0f2f4);
    overflow: hidden;
}
.ft-track span {
    display: block;
    height: 100%;
    border-radius: 999px;
    background: #16a34a;
}
.ft-progress {
    flex: 1 1 auto;
    min-width: 0;
    padding-right: .4rem;
}
.ft-scroll {
    max-height: 18rem;
    overflow: auto;
}
.ft-table {
    width: 100%;
    margin: 0;
    border-collapse: collapse;
    font-size: .8rem;
}
.ft-table th {
    position: sticky;
    top: 0;
    z-index: 1;
    padding: .3rem .4rem;
    border-top: 0;
    background: var(--fg-color, #fff);
    font-size: .64rem;
    font-weight: 600;
    letter-spacing: .04em;
    text-transform: uppercase;
    text-align: left;
    white-space: nowrap;
    color: var(--text-muted, #7c8792);
}
.ft-table td {
    padding: .35rem .4rem;
    border-bottom: 1px solid var(--border-color, #f2f4f7);
    color: var(--text-color, #1f272e);
    vertical-align: middle;
}
.ft-table tr:last-child td {
    border-bottom: 0;
}
.ft-table .r {
    text-align: right;
}
.ft-num {
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}
.ft-pill {
    display: inline-block;
    padding: 0 .45rem;
    border-radius: 999px;
    font-size: .66rem;
    font-weight: 600;
    line-height: 1.65;
}
.ft-closed {
    background: #dcfce7;
    color: #166534;
}
.ft-info {
    background: #dbeafe;
    color: #1e40af;
}
.ft-draft {
    background: #e5e7eb;
    color: #374151;
}
.ft-muted {
    color: var(--text-muted, #7c8792);
}
.ft-empty {
    margin: 0;
    padding: .6rem 0;
    font-size: .8rem;
}

