var root = root_element;
// The desk wraps every Custom HTML Block in its own widget box (title, padding
// and background). Each panel below ships its own card, so the extra chrome is
// removed to avoid a duplicated heading and a box inside a box.
var ft_host = root.host;
var ft_widget = ft_host && ft_host.closest ? ft_host.closest(".widget") : null;
if (ft_widget) {
    ft_widget.style.background = "transparent";
    ft_widget.style.padding = "0";
    ft_widget.style.borderRadius = "0";
    var ft_label = ft_widget.querySelector(".widget-label");
    if (ft_label) ft_label.style.display = "none";
    var ft_body = ft_widget.querySelector(".widget-body");
    if (ft_body) ft_body.style.paddingTop = "0";
}
var esc = function (value) {
    if (value === null || value === undefined) return "";
    var mapping = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
    return String(value).replace(/[&<>"']/g, function (character) {
