var empty = function (message) { return '<p class="ft-muted ft-empty">' + esc(message) + '</p>'; };
var show_error = function () { fill("rows", empty("Could not load this panel.")); };
var load = function (method, done) {
    frappe.call({
        method: method,
        args: {},
