    var classes = { Closed: "ft-closed", Submitted: "ft-info", Draft: "ft-draft", Cancelled: "ft-draft" };
    return '<span class="ft-pill ' + (classes[status] || "ft-draft") + '">' + esc(status || "—") + "</span>";
};
